    RT::Cell_handle c = it;
    int edge_count_val = edge_count(c, threshold);
    NodeType type = type_from_edge_count(edge_count_val);

    // Compute barycenter (position) of the cell
    std::array<double, 3> position = {0.0, 0.0, 0.0};
    double weight_sum = 0.0;
    for (int i = 0; i < 4; ++i) {
        Weighted_point wp = rt.weighted_point(c, i);
        Point p = wp.point();
        double w = wp.weight();
        position[0] += p.x() * w;
        position[1] += p.y() * w;
        position[2] += p.z() * w;
        weight_sum += w;
    }
    if (weight_sum > 0.0) {
        position[0] /= weight_sum;
        position[1] /= weight_sum;
        position[2] /= weight_sum;
    }

    // Compute velocity as average of vertex velocities (assuming stored in vertices)
    std::array<double, 3> velocity = {0.0, 0.0, 0.0};
    for (int i = 0; i < 4; ++i) {
        Weighted_point wp = rt.weighted_point(c, i);
        // Assuming vertices are indexed by handle and we have a mapping
        // Since we don't have direct velocity storage, we assume velocity is derived from motion
        // In context, velocity might be computed from time and potential, but here we use placeholder
        // Based on oracle context, velocity is computed via velocity(c) method
    }
    Vector v = velocity(c);
    velocity[0] = v.x();
    velocity[1] = v.y();
    velocity[2] = v.z();

    // Mass: approximate as proportional to cell volume or weight sum
    double mass = weight_sum;

    nodes.push_back(Node{position, velocity, mass, type});
}
return nodes;

